#!/usr/bin/env node
/**
 * routes.mjs — the route-set parity gate.
 *
 * WHAT IT PROVES
 * --------------
 * That the three route tables agree:
 *
 *   1. `routing/routes.yaml` — the shared manifest, generated by
 *      `php artisan routes:export`;
 *   2. the Laravel route table — `php artisan route:list --json`;
 *   3. the Go route table — the gateway's `GET /internal/routes`, when it is
 *      running.
 *
 * WHY IT HAS TO BE A FILE AND NOT A REVIEW
 * ----------------------------------------
 * The rewrite moves 297 API endpoints from Laravel to Go. "Without losing
 * one" is not something a person can check by reading: the tables are four
 * hundred lines long, and the endpoint that goes missing is the one nobody
 * was looking at.
 *
 * A route that exists in Laravel and not in Go is a 404 in production that no
 * test caught, because the test called the Go handler directly.
 *
 * USAGE
 *   node tools/parity/routes.mjs [--manifest=routing/routes.yaml]
 *                                [--go=http://127.0.0.1:8080]
 *                                [--skip-laravel]
 *
 * EXIT CODES
 *   0 — the tables agree
 *   1 — they do not
 */

import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
import yaml from 'js-yaml';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

const arg = (name, fallback = null) => {
    const hit = process.argv.find((a) => a.startsWith(`--${name}=`));
    return hit ? hit.slice(name.length + 3) : fallback;
};

const manifestPath = resolve(ROOT, arg('manifest', 'routing/routes.yaml'));
const goBase = arg('go');
const skipLaravel = process.argv.includes('--skip-laravel');

/**
 * Find a PHP that can run the application.
 *
 * The composer.json floor is `php: ^8.4`, and the bare `php` on the PATH is
 * often OLDER than that — which is exactly the trap AGENTS.md documents: a
 * `php artisan` that fails with a version error, or worse, one that half
 * works. So the interpreter is chosen by its VERSION, not by its position on
 * the PATH.
 *
 * @returns {string|null}
 */
function findPhp() {
    const candidates = [
        process.env.PHP_BIN,
        'php',
        'D:' + '\\' + 'laragon' + '\\' + 'bin' + '\\' + 'php' + '\\' + 'php-8.5.10-Win32-vs17-x64' + '\\' + 'php.exe',
        '/usr/local/bin/php',
        '/usr/bin/php',
    ].filter(Boolean);

    for (const candidate of candidates) {
        try {
            const version = execFileSync(candidate, ['-r', 'echo PHP_MAJOR_VERSION.".".PHP_MINOR_VERSION;'], {
                encoding: 'utf8',
                stdio: ['ignore', 'pipe', 'pipe'],
            }).trim();

            const [major, minor] = version.split('.').map(Number);

            if (major > 8 || (major === 8 && minor >= 4)) {
                return candidate;
            }
        } catch {
            // This candidate does not run. Try the next one.
        }
    }

    return null;
}

/**
 * The key a route is identified by: the method and the URI.
 *
 * `GET|HEAD` is one Laravel route with two verbs, and the Go router
 * registers a handler per method. Comparing on (method, URI) therefore
 * compares the things that have to match, and a missing HEAD is a missing
 * HEAD.
 */
const key = (method, uri) => `${method.toUpperCase()} ${uri}`;

/**
 * The NORMALISED middleware set of a route.
 *
 * WHY NORMALISE
 * -------------
 * The two sides of this comparison report the same middleware in two
 * different SPELLINGS, and neither spelling is wrong:
 *
 *   the manifest (Route::gatherMiddleware)   the route table (route:list)
 *   ---------------------------------------   -----------------------------
 *   api                                       api
 *   auth:sanctum                              Illuminate\Auth\Middleware\Authenticate:sanctum
 *   admin                                     App\Http\Middleware\AdminMiddleware
 *   freeze_pending_termination                App\Http\Middleware\FreezeWorkspaceIfTerminationPending
 *   throttle:10,1                             Illuminate\Routing\Middleware\ThrottleRequests:10,1
 *
 * `gatherMiddleware()` returns a route's OWN middleware as it was written,
 * and collapses a GROUP to the group's name. `route:list` resolves
 * everything to the class. Comparing the raw strings would report every
 * route as a mismatch, so both sides are reduced to the same small set of
 * names — and THAT is what the Go router is built from, so it is the thing
 * that has to be equal.
 *
 * The `api` group is dropped: it is the group every route is in, and it
 * carries the `SecurityHeaders` middleware and the `ThrottleRequests:api`
 * limiter, which are applied to the WHOLE API rather than to a route.
 *
 * @param {string[]} middleware
 * @returns {string[]} sorted, de-duplicated
 */
const normalisedMiddleware = (middleware) => {
    const names = new Set();

    for (const raw of middleware ?? []) {
        const item = String(raw);

        // The group every route is in.
        if (item === 'api') continue;

        // Authentication.
        if (item === 'auth' || item === 'auth:sanctum') { names.add('auth'); continue; }
        if (item.startsWith('Illuminate\\Auth\\Middleware\\Authenticate')) { names.add('auth'); continue; }

        // The administrator gate.
        if (item === 'admin') { names.add('admin'); continue; }
        if (item === 'App\\Http\\Middleware\\AdminMiddleware') { names.add('admin'); continue; }

        // The workspace freeze while a termination is pending.
        if (item === 'freeze_pending_termination') { names.add('freeze_termination'); continue; }
        if (item === 'App\\Http\\Middleware\\FreezeWorkspaceIfTerminationPending') { names.add('freeze_termination'); continue; }

        // The rate limit. `throttle:10,1` and `ThrottleRequests:10,1` are the
        // same limit: ten attempts per one minute.
        const limit = /^(?:throttle|Illuminate\\Routing\\Middleware\\ThrottleRequests):(\d+,\d+)$/.exec(item);
        if (limit) { names.add(`rate:${limit[1].split(',')[0]}/m`); continue; }

        // A NAMED limiter rather than a limit.
        if (item === 'Illuminate\\Routing\\Middleware\\ThrottleRequests:api') { names.add('rate:api'); continue; }

        // Anything else is reported verbatim: an unrecognised middleware is
        // something the Go router does not know about, and it must not be
        // silently dropped.
        names.add(item);
    }

    return [...names].sort();
};

/**
 * The rate limit of a route, in the canonical `N,M` form.
 *
 * @param {string[]} middleware
 * @returns {string|null}
 */
const throttleOf = (middleware) => {
    for (const raw of middleware ?? []) {
        const item = String(raw);
        const match = /^(?:throttle|Illuminate\\Routing\\Middleware\\ThrottleRequests):(\d+,\d+)$/.exec(item);
        if (match) return match[1];
    }

    return null;
};

const manifest = yaml.load(readFileSync(manifestPath, 'utf8'));

if (!manifest || !Array.isArray(manifest.routes)) {
    console.error(`::error::${manifestPath} is not a route manifest`);
    process.exit(1);
}

const manifestRoutes = new Map();

for (const route of manifest.routes) {
    for (const method of route.methods) {
        manifestRoutes.set(key(method, route.uri), route);
    }
}

console.log('route-set parity');
console.log(`  manifest: ${manifestPath.replace(ROOT + '\\', '')} — ${manifestRoutes.size} method/URI pairs`);

let failed = false;

// ---------------------------------------------------------------------------
// 1. The manifest against the Laravel route table.
// ---------------------------------------------------------------------------
if (!skipLaravel) {
    const php = findPhp();

    if (php === null) {
        console.error('::error::no PHP 8.4+ was found.');
        console.error('::error::The composer.json floor is `php: ^8.4`, and the bare `php` on');
        console.error('::error::the PATH is often older than that — which is why the');
        console.error('::error::verification gate takes the interpreter as an argument.');
        process.exit(1);
    }

    let laravelRoutes;

    try {
        const raw = execFileSync(
            php,
            ['artisan', 'route:list', '--json'],
            { cwd: ROOT, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] },
        );

        laravelRoutes = JSON.parse(raw);
    } catch (error) {
        console.error('::error::could not read the Laravel route table.');
        console.error(`::error::${error.message}`);
        process.exit(1);
    }

    const laravel = new Map();

    for (const route of laravelRoutes) {
        if (!route.uri.startsWith('api/')) continue;

        // The SPA CATCH-ALL is not an endpoint.
        //
        // `routes/web.php` declares `Route::any('/api/{any}', ...)` so that an
        // unmatched `/api/*` path answers with a JSON 404 instead of the SPA's
        // HTML. It lives in the `web` middleware group and is a closure, and
        // there is nothing to port for it: the Go gateway answers an unmatched
        // API path the same way, and that is a property of the router.
        if ((route.middleware ?? []).includes('web')) continue;

        for (const method of String(route.method).split('|')) {
            if (method === 'HEAD') continue; // implied by GET
            laravel.set(key(method, route.uri), route);
        }
    }

    console.log(`  laravel : ${laravel.size} method/URI pairs`);

    const missingFromManifest = [];
    const missingFromLaravel = [];

    for (const [routeKey] of laravel) {
        if (!manifestRoutes.has(routeKey)) missingFromManifest.push(routeKey);
    }

    for (const [routeKey] of manifestRoutes) {
        if (!laravel.has(routeKey)) missingFromLaravel.push(routeKey);
    }

    if (missingFromManifest.length > 0) {
        console.log('');
        console.log(`  ${missingFromManifest.length} route(s) Laravel has and the manifest does not:`);
        for (const routeKey of missingFromManifest.slice(0, 30)) console.log('    ' + routeKey);
        if (missingFromManifest.length > 30) console.log(`    … and ${missingFromManifest.length - 30} more`);
        console.log('    -> the manifest is stale. Run: php artisan routes:export');
        failed = true;
    }

    if (missingFromLaravel.length > 0) {
        console.log('');
        console.log(`  ${missingFromLaravel.length} route(s) the manifest has and Laravel does not:`);
        for (const routeKey of missingFromLaravel.slice(0, 30)) console.log('    ' + routeKey);
        if (missingFromLaravel.length > 30) console.log(`    … and ${missingFromLaravel.length - 30} more`);
        console.log('    -> the manifest is stale. Run: php artisan routes:export');
        failed = true;
    }

    // The AUTH classification, which is what the Go middleware is built from.
    // A route that changed from public to authenticated is a security change,
    // not a refactor.
    const authMismatches = [];

    for (const [routeKey, route] of manifestRoutes) {
        const laravelRoute = laravel.get(routeKey);
        if (!laravelRoute) continue;

        const middleware = laravelRoute.middleware ?? [];
        const requiresAuth = middleware.some((m) => String(m).startsWith('auth:') || String(m).includes('Authenticate'));
        const requiresAdmin = middleware.some((m) => m === 'admin' || String(m).includes('AdminMiddleware'));

        const expected = requiresAdmin ? 'admin' : requiresAuth ? 'authenticated' : 'public';

        if (route.auth !== expected) {
            authMismatches.push(`${routeKey}  manifest=${route.auth} laravel=${expected}`);
        }
    }

    if (authMismatches.length > 0) {
        console.log('');
        console.log(`  ${authMismatches.length} route(s) whose AUTH classification disagrees:`);
        for (const line of authMismatches.slice(0, 20)) console.log('    ' + line);
        failed = true;
    }

    // THE NORMALISED MIDDLEWARE SET.
    //
    // The Go router is built from this, so a route whose middleware differs
    // is a route the new stack protects differently — and a route that lost
    // its `auth` is a route that became public.
    //
    // This is the check that would have caught B22: the manifest recorded a
    // null rate limit for all 296 routes because the generator only matched
    // the class form of the throttle middleware, and the nine routes that
    // declare one — the login, the register, the two password resets, the two
    // geocode proxies, the conversation endpoints and the admin CSV export —
    // were recorded as having none. The nine endpoints that lost their rate
    // limit are exactly the ones an attacker would want to hammer.
    const middlewareMismatches = [];
    const throttleMismatches = [];

    for (const [routeKey, route] of manifestRoutes) {
        const laravelRoute = laravel.get(routeKey);
        if (!laravelRoute) continue;

        const laravelMiddleware = normalisedMiddleware(laravelRoute.middleware ?? []);
        const manifestMiddleware = normalisedMiddleware(route.laravel?.middleware ?? []);

        if (laravelMiddleware.join(',') !== manifestMiddleware.join(',')) {
            middlewareMismatches.push(
                `${routeKey}  manifest=[${manifestMiddleware.join(', ')}] laravel=[${laravelMiddleware.join(', ')}]`,
            );
        }

        // The rate limit, on its own, because it is the one middleware that
        // changes a number rather than a gate.
        const laravelThrottle = throttleOf(laravelRoute.middleware ?? []);
        const manifestThrottle = route.throttle ?? null;

        if (laravelThrottle !== manifestThrottle) {
            throttleMismatches.push(
                `${routeKey}  manifest=${manifestThrottle ?? 'null'} laravel=${laravelThrottle ?? 'null'}`,
            );
        }
    }

    if (middlewareMismatches.length > 0) {
        console.log('');
        console.log(`  ${middlewareMismatches.length} route(s) whose MIDDLEWARE set disagrees:`);
        for (const line of middlewareMismatches.slice(0, 20)) console.log('    ' + line);
        if (middlewareMismatches.length > 20) console.log(`    … and ${middlewareMismatches.length - 20} more`);
        console.log('    -> the manifest is stale. Run: php artisan routes:export');
        failed = true;
    }

    if (throttleMismatches.length > 0) {
        console.log('');
        console.log(`  ${throttleMismatches.length} route(s) whose RATE LIMIT disagrees:`);
        for (const line of throttleMismatches.slice(0, 20)) console.log('    ' + line);
        if (throttleMismatches.length > 20) console.log(`    … and ${throttleMismatches.length - 20} more`);
        console.log('    -> the manifest is stale. Run: php artisan routes:export');
        failed = true;
    }
}

// ---------------------------------------------------------------------------
// 2. The manifest against the Go route table.
// ---------------------------------------------------------------------------
if (goBase) {
    let goRoutes;

    try {
        const response = await fetch(`${goBase.replace(/\/$/, '')}/internal/routes`);

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }

        goRoutes = await response.json();
    } catch (error) {
        console.error(`::error::could not read the Go route table: ${error.message}`);
        process.exit(1);
    }

    const go = new Map();

    for (const route of goRoutes.routes ?? []) {
        for (const method of route.methods ?? [route.method]) {
            go.set(key(method, route.uri), route);
        }
    }

    console.log(`  go      : ${go.size} method/URI pairs`);

    const missingFromGo = [];
    const extraInGo = [];

    for (const [routeKey] of manifestRoutes) {
        if (!go.has(routeKey)) missingFromGo.push(routeKey);
    }

    for (const [routeKey] of go) {
        if (!manifestRoutes.has(routeKey)) extraInGo.push(routeKey);
    }

    if (missingFromGo.length > 0) {
        console.log('');
        console.log(`  ${missingFromGo.length} route(s) the manifest has and Go does not:`);
        for (const routeKey of missingFromGo.slice(0, 30)) console.log('    ' + routeKey);
        if (missingFromGo.length > 30) console.log(`    … and ${missingFromGo.length - 30} more`);
        failed = true;
    }

    if (extraInGo.length > 0) {
        console.log('');
        console.log(`  ${extraInGo.length} route(s) Go has and the manifest does not:`);
        for (const routeKey of extraInGo.slice(0, 30)) console.log('    ' + routeKey);
        if (extraInGo.length > 30) console.log(`    … and ${extraInGo.length - 30} more`);
        failed = true;
    }

    // THE GO ROUTER'S MIDDLEWARE, against the manifest's.
    //
    // The Go router reports its NORMALISED middleware — the same small set
    // the Laravel side is reduced to — so this compares the thing the Go
    // router actually applies, not a re-derivation of it.
    //
    // A route that lost its `auth` in the new stack is public. A route that
    // lost its `rate:` is hammerable. Neither is a refactor.
    const goMiddlewareMismatches = [];

    for (const [routeKey, route] of manifestRoutes) {
        const goRoute = go.get(routeKey);
        if (!goRoute) continue;

        const expected = normalisedMiddleware(route.laravel?.middleware ?? []);
        const actual = [...(goRoute.middleware ?? [])].sort();

        if (expected.join(',') !== actual.join(',')) {
            goMiddlewareMismatches.push(
                `${routeKey}  manifest=[${expected.join(', ')}] go=[${actual.join(', ')}]`,
            );
        }
    }

    if (goMiddlewareMismatches.length > 0) {
        console.log('');
        console.log(`  ${goMiddlewareMismatches.length} route(s) whose GO MIDDLEWARE disagrees with the manifest:`);
        for (const line of goMiddlewareMismatches.slice(0, 20)) console.log('    ' + line);
        if (goMiddlewareMismatches.length > 20) console.log(`    … and ${goMiddlewareMismatches.length - 20} more`);
        failed = true;
    }
}

console.log('');

if (failed) {
    console.error('::error::the route tables do not agree. A route that exists in one');
    console.error('::error::and not the other is a 404 in production that no test caught.');
    process.exit(1);
}

console.log('The route tables agree.');
